"use client";

import { FormEvent, useEffect, useState } from "react";
import { api, ApiError } from "@/lib/api-client";
import { BarChart3, Megaphone, MousePointerClick, Eye, CalendarDays } from "lucide-react";

type Plan={durationDays:number;price:number;label?:string}; type Campaign={id:string;name:string;objective:string;target_type:string;duration_days:number;price:number;status:string;start_at?:string;end_at?:string}; type Analytics={metrics:{impressions:number;clicks:number;ctr:number;destinationViews:number;checkoutStarts:number;purchases:number;bookings:number}};

export default function AdsPage(){
 const [plans,setPlans]=useState<Plan[]>([]);const [campaigns,setCampaigns]=useState<Campaign[]>([]);const [selected,setSelected]=useState<Campaign|null>(null);const [analytics,setAnalytics]=useState<Analytics|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 const [form,setForm]=useState({name:"",objective:"STORE_VISITS",targetType:"STORE",targetId:"",targetCategory:"",targetLocation:"",durationDays:"7"});
 async function load(){try{const [p,c]=await Promise.all([api.get<{plans:Plan[]}>("/api/ads/plans"),api.get<{campaigns:Campaign[]}>("/api/ads/campaigns")]);setPlans(p.plans);setCampaigns(c.campaigns);}catch(e){setError(e instanceof ApiError?e.message:"Unable to load Ad Centre");}}
 useEffect(()=>{void load()},[]);
 async function create(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const r=await api.post<{checkoutUrl:string}>("/api/ads/campaigns",{...form,durationDays:Number(form.durationDays),targetId:form.targetId||undefined,targetCategory:form.targetCategory||undefined,targetLocation:form.targetLocation||undefined});window.location.href=r.checkoutUrl;}catch(e){setError(e instanceof ApiError?e.message:"Unable to start campaign");setBusy(false);}}
 async function inspect(c:Campaign){setSelected(c);setAnalytics(null);try{setAnalytics(await api.get<Analytics>(`/api/ads/campaigns/${c.id}/analytics`));}catch(e){setError(e instanceof ApiError?e.message:"Unable to load analytics");}}
 return <div className="shell py-8"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-ember-600">TTFL Advertising</p><h1 className="mt-1 text-2xl font-bold text-graphite-900 dark:text-white">Ad Centre</h1><p className="mt-1 max-w-2xl text-sm text-graphite-600 dark:text-graphite-400">Promote your store, products, services, or upcoming launches with simple fixed-duration pricing.</p></div>
 <div className="mt-6 grid gap-3 sm:grid-cols-4">{plans.map(p=><button key={p.durationDays} type="button" onClick={()=>setForm(x=>({...x,durationDays:String(p.durationDays)}))} className={`rounded-card border p-4 text-left ${form.durationDays===String(p.durationDays)?"border-ember-600 ring-2 ring-ember-100 dark:ring-ember-900":"border-graphite-200 dark:border-graphite-700"}`}><div className="flex items-center justify-between"><span className="text-sm font-semibold">{p.durationDays} day{p.durationDays===1?"":"s"}</span>{p.label&&<span className="text-[10px] font-bold uppercase text-ember-600">{p.label}</span>}</div><p className="mt-2 text-xl font-bold">₦{p.price.toLocaleString()}</p></button>)}</div>
 <div className="mt-6 grid gap-6 lg:grid-cols-[1.05fr_.95fr]"><form onSubmit={create} className="rounded-card border border-graphite-200 bg-white p-6 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-card bg-ember-100 text-ember-700 dark:bg-ember-900/40 dark:text-ember-300"><Megaphone className="h-5 w-5"/></span><div><h2 className="font-bold">Create campaign</h2><p className="text-xs text-graphite-500">Payment is handled securely by Paystack.</p></div></div><div className="mt-5 space-y-4"><label className="block"><span className="text-sm font-semibold">Campaign name</span><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="mt-2 field" placeholder="Weekend service promotion"/></label><label className="block"><span className="text-sm font-semibold">Goal</span><select value={form.objective} onChange={e=>setForm({...form,objective:e.target.value})} className="mt-2 field"><option value="STORE_VISITS">Store visits</option><option value="PRODUCT_VIEWS">Product views</option><option value="SERVICE_BOOKINGS">Service bookings</option><option value="ORDERS">Orders</option><option value="STORE_PROMOTION">Store promotion</option><option value="SPECIAL_OFFER">Special offer</option></select></label><label className="block"><span className="text-sm font-semibold">Promote</span><select value={form.targetType} onChange={e=>setForm({...form,targetType:e.target.value})} className="mt-2 field"><option value="STORE">My store</option><option value="PRODUCT">A product</option><option value="SERVICE">A service</option><option value="COMING_SOON">Coming Soon listing</option></select></label><label className="block"><span className="text-sm font-semibold">Target ID <span className="font-normal text-graphite-400">(optional for store campaigns)</span></span><input value={form.targetId} onChange={e=>setForm({...form,targetId:e.target.value})} className="mt-2 field" placeholder="Product or service ID"/></label><div className="grid gap-4 sm:grid-cols-2"><label><span className="text-sm font-semibold">Category</span><input value={form.targetCategory} onChange={e=>setForm({...form,targetCategory:e.target.value})} className="mt-2 field" placeholder="Phones & Tablets"/></label><label><span className="text-sm font-semibold">Location</span><input value={form.targetLocation} onChange={e=>setForm({...form,targetLocation:e.target.value})} className="mt-2 field" placeholder="Lagos"/></label></div><input type="hidden" value={form.durationDays}/>{error&&<p className="text-sm font-medium text-ember-600">{error}</p>}<button disabled={busy} className="w-full rounded-card bg-ember-600 px-4 py-3 text-sm font-semibold text-white hover:bg-ember-700 disabled:opacity-60">{busy?"Opening payment…":`Pay ₦${(plans.find(p=>String(p.durationDays)===form.durationDays)?.price??0).toLocaleString()} and launch`}</button></div></form>
 <section className="rounded-card border border-graphite-200 bg-white p-6 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex items-center justify-between"><div><h2 className="font-bold">Campaign analytics</h2><p className="text-xs text-graphite-500">Live event totals for your campaigns.</p></div><BarChart3 className="h-5 w-5 text-graphite-400"/></div>{selected&&analytics?<div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">{[[Eye,"Impressions",analytics.metrics.impressions],[MousePointerClick,"Clicks",analytics.metrics.clicks],[BarChart3,"CTR",`${analytics.metrics.ctr}%`],[Eye,"Destination views",analytics.metrics.destinationViews],[CalendarDays,"Checkout starts",analytics.metrics.checkoutStarts],[MousePointerClick,"Purchases / bookings",analytics.metrics.purchases+analytics.metrics.bookings]].map(([Icon,label,value]:any)=><div key={label} className="rounded-card bg-cloud-50 p-4 dark:bg-graphite-800"><Icon className="h-4 w-4 text-graphite-500"/><p className="mt-3 text-xl font-bold">{value}</p><p className="text-xs text-graphite-500">{label}</p></div>)}</div>:<p className="mt-8 text-center text-sm text-graphite-500">Select a campaign below to view its analytics.</p>}
 <div className="mt-6 space-y-2">{campaigns.map(c=><button key={c.id} onClick={()=>void inspect(c)} className="w-full rounded-card border border-graphite-200 p-4 text-left hover:border-ember-500 dark:border-graphite-700"><div className="flex items-center justify-between gap-3"><span className="font-semibold">{c.name}</span><span className="text-xs font-semibold">{c.status}</span></div><p className="mt-1 text-xs text-graphite-500">{c.duration_days} days · {c.target_type} · ₦{Number(c.price).toLocaleString()}</p></button>)}{campaigns.length===0&&<p className="text-sm text-graphite-500">No campaigns yet.</p>}</div></section></div></div>
}
